/**
 * @summary Validate a schedule and return issues
 */
export const getValidateScheduleUrl = (wardId: number, scheduleId: number) => {
  return `/api/wards/${wardId}/schedules/${scheduleId}/validate`;
};

export const validateSchedule = async (
  wardId: number,
  scheduleId: number,
  options?: RequestInit,
): Promise<ValidationResult[]> => {
  return customFetch<ValidationResult[]>(
    getValidateScheduleUrl(wardId, scheduleId),
    {
      ...options,
      method: "POST",
    },
  );
};

export const getValidateScheduleMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof validateSchedule>>,
    TError,
    { wardId: number; scheduleId: number },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof validateSchedule>>,
  TError,
  { wardId: number; scheduleId: number },
  TContext
> => {
  const mutationKey = ["validateSchedule"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof validateSchedule>>,
    { wardId: number; scheduleId: number }
  > = (props) => {
    const { wardId, scheduleId } = props ?? {};

    return validateSchedule(wardId, scheduleId, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type ValidateScheduleMutationResult = NonNullable<
  Awaited<ReturnType<typeof validateSchedule>>
>;

export type ValidateScheduleMutationError = ErrorType<unknown>;

/**
 * @summary Validate a schedule and return issues
 */
export const useValidateSchedule = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof validateSchedule>>,
    TError,
    { wardId: number; scheduleId: number },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof validateSchedule>>,
  TError,
  { wardId: number; scheduleId: number },
  TContext
> => {
  return useMutation(getValidateScheduleMutationOptions(options));
};

/**
 * @summary Get actionable recommendations for schedule issues
 */
export const getGetScheduleRecommendationsUrl = (
  wardId: number,
  scheduleId: number,
) => {
  return `/api/wards/${wardId}/schedules/${scheduleId}/recommendations`;
};

export const getScheduleRecommendations = async (
  wardId: number,
  scheduleId: number,
  options?: RequestInit,
): Promise<ScheduleRecommendationSummary> => {
  return customFetch<ScheduleRecommendationSummary>(
    getGetScheduleRecommendationsUrl(wardId, scheduleId),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetScheduleRecommendationsQueryKey = (
  wardId: number,
  scheduleId: number,
) => {
  return [
    `/api/wards/${wardId}/schedules/${scheduleId}/recommendations`,
  ] as const;
};

export const getGetScheduleRecommendationsQueryOptions = <
  TData = Awaited<ReturnType<typeof getScheduleRecommendations>>,
  TError = ErrorType<unknown>,
>(
  wardId: number,
  scheduleId: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getScheduleRecommendations>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ??
    getGetScheduleRecommendationsQueryKey(wardId, scheduleId);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getScheduleRecommendations>>
  > = ({ signal }) =>
    getScheduleRecommendations(wardId, scheduleId, {
      signal,
      ...requestOptions,
    });

  return {
    queryKey,
    queryFn,
    enabled: !!(wardId && scheduleId),
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getScheduleRecommendations>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetScheduleRecommendationsQueryResult = NonNullable<
  Awaited<ReturnType<typeof getScheduleRecommendations>>
>;
export type GetScheduleRecommendationsQueryError = ErrorType<unknown>;

/**
 * @summary Get actionable recommendations for schedule issues
 */

export function useGetScheduleRecommendations<
  TData = Awaited<ReturnType<typeof getScheduleRecommendations>>,
  TError = ErrorType<unknown>,
>(
  wardId: number,
  scheduleId: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getScheduleRecommendations>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetScheduleRecommendationsQueryOptions(
    wardId,
    scheduleId,
    options,
  );

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
